#!/usr/bin/env python3
"""Read ids.txt and print the next order id to stdout."""

import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def base36_increment(s: str) -> str:
    """Increment a base-36 string by 1, returning the result.

    Keeps the same length unless the input is all Z's (e.g. ZZZZ -> 10000).
    """
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        idx = BASE36.index(chars[i].upper())
        if idx < 35:
            chars[i] = BASE36[idx + 1]
            return ''.join(chars)
        chars[i] = '0'
    # every digit wrapped — prepend '1'
    return '1' + '0' * len(s)


def main() -> None:
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('ORD-0000')
        return

    if not lines:
        print('ORD-0000')
        return

    last_id = lines[-1]
    suffix = last_id.split('-', 1)[1]  # e.g. "243G"
    next_suffix = base36_increment(suffix)
    print(f'ORD-{next_suffix}')


if __name__ == '__main__':
    main()

