"""Read ids.txt and print the next sequential order id."""

import os

IDS_FILE = "ids.txt"
PREFIX = "ORD-"
CODE_LEN = 4


def to_base36(n: int) -> str:
    """Convert an integer to zero-padded base36 string of length CODE_LEN."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(CODE_LEN):
        n, rem = divmod(n, 36)
        result.append(chars[rem])
    return "".join(reversed(result))


def from_base36(s: str) -> int:
    """Convert a base36 string to an integer."""
    return int(s, 36)


def main() -> None:
    if not os.path.exists(IDS_FILE):
        # No ids issued yet; start from zero
        next_id = 0
    else:
        with open(IDS_FILE) as f:
            lines = [line.strip() for line in f if line.strip()]

        if not lines:
            next_id = 0
        else:
            last_line = lines[-1]
            suffix = last_line[len(PREFIX):]
            last_num = from_base36(suffix)
            next_id = last_num + 1

    next_code = to_base36(next_id)
    print(f"{PREFIX}{next_code}")


if __name__ == "__main__":
    main()

