#!/usr/bin/env python3
"""Print report file names under reports/ in report order."""

import os
import re


def report_key(name: str) -> int:
    """Extract the numeric part from a report filename for sorting."""
    match = re.search(r"report-(\d+)\.txt$", name)
    if match is None:
        return float("inf")
    return int(match.group(1))


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")
    files = [f for f in os.listdir(reports_dir) if f.endswith(".txt")]
    files.sort(key=report_key)
    for f in files:
        print(f)


if __name__ == "__main__":
    main()

