import os
import re


def report_order_key(filename: str) -> tuple:
    """Return a sort key that respects the numeric order of report-<n>.txt names."""
    m = re.search(r"(\d+)", filename)
    if m:
        return (int(m.group(1)), filename)
    return (float("inf"), filename)


