    reports_dir = "reports"
    if not os.path.isdir(reports_dir):
        print(f"error: '{reports_dir}' directory not found", file=__import__("sys").stderr)
        raise SystemExit(1)

    filenames = sorted(os.listdir(reports_dir), key=report_order_key)
    for name in filenames:
        path = os.path.join(reports_dir, name)
        if os.path.isfile(path):
            print(name)


if __name__ == "__main__":
    main()

