"""Rotate old entries from app.log to archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message. Entries
strictly older than 7 days before AS_OF are moved to archive.log (appended,
preserving order). app.log is rewritten with the remaining entries in their
original order.
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading YYYY-MM-DD HH:MM:SS from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    try:
        with open("app.log", "r", encoding="utf-8") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    # Strip trailing newlines for consistent handling
    lines = [line.rstrip("\n") for line in lines]

    # Filter out any trailing empty lines from the file
    while lines and lines[-1] == "":
        lines.pop()

    kept: list[str] = []
    rotated: list[str] = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is None:
            kept.append(line)
        elif ts < cutoff:
            rotated.append(line)
        else:
            kept.append(line)

    # Append rotated entries to archive.log
    if rotated:
        with open("archive.log", "a", encoding="utf-8") as f:
            for line in rotated:
                f.write(line + "\n")

    # Rewrite app.log with kept entries
    with open("app.log", "w", encoding="utf-8") as f:
        for line in kept:
            f.write(line + "\n")


if __name__ == "__main__":
    main()
